@Component
public class JwtLogFilter extends OncePerRequestFilter {
    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain) 
            throws ServletException, IOException {
        String authHeader = request.getHeader("Authorization");
        if (authHeader != null && authHeader.startsWith("Bearer ")) {
            // Mask the token before it reaches any logging framework
            String maskedToken = "Bearer " + authHeader.substring(7, 12) + "*****";
            MDC.put("jwt_token", maskedToken);
        }
        try {
            chain.doFilter(request, response);
        } finally {
            MDC.remove("jwt_token");
        }
    }
}
